source.raw:
.paper-foxed::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    radial-gradient(
      circle at 12% 18%,
      color-mix(in srgb, var(--foxing-base) 18%, transparent) 0 1.2px,
      transparent 2.5px
    ),
    radial-gradient(
      circle at 88% 32%,
      color-mix(in srgb, var(--foxing-base) 16%, transparent) 0 0.9px,
      transparent 2px
    ),
    radial-gradient(
      circle at 24% 78%,
      color-mix(in srgb, var(--foxing-base) 14%, transparent) 0 1.4px,
      transparent 2.8px
    ),
    radial-gradient(
      circle at 76% 88%,
      color-mix(in srgb, var(--foxing-base) 18%, transparent) 0 1px,
      transparent 2.2px
    ),
    radial-gradient(
      circle at 50% 50%,
      color-mix(in srgb, var(--foxing-base) 12%, transparent) 0 0.8px,
      transparent 2px
    );
  opacity: 0.7;
  mix-blend-mode: multiply;
}
